"""GIVEN helpers for the fine-tuning project. Do not edit this file: the grader runs the same code.
(The test labels are visible so that you can compute your metrics. Using them for anything but reporting is an honesty violation.)

  load_split()          the fixed train / validation / test split of Financial PhraseBank "sentences_allagree"
                        (same seed and same split for everybody, whatever toolkit you use)
  write_submission(...) writes results.csv, predictions.csv and environment.txt from what YOU computed
  check_submission(...) re-reads those files, recomputes every accuracy from your predictions, prints the summary

Labels: 0 = negative, 1 = neutral, 2 = positive (same as the HuggingFace dataset).
Needs: numpy, pandas, huggingface_hub (no `datasets` version issues: the raw file is read directly).
"""
import hashlib, io, os, platform, subprocess, sys, zipfile
import numpy as np, pandas as pd

SEED = 7773                       # fixed for everybody: do not change
FRACTIONS = (0.70, 0.15, 0.15)    # train / validation / test
LABELS = {"negative": 0, "neutral": 1, "positive": 2}
MODELS = ["model_1", "model_2", "model_3", "model_4", "model_5", "model_6"]   # Models 1 to 6 of the assignment
SUBSETS = {"allagree": "Sentences_AllAgree.txt", "75agree": "Sentences_75Agree.txt",
           "66agree": "Sentences_66Agree.txt", "50agree": "Sentences_50Agree.txt"}


def load_phrasebank(subset="allagree"):
    """All sentences of one subset, in the original file order. Returns a DataFrame: id, text, label."""
    from huggingface_hub import hf_hub_download
    path = hf_hub_download("takala/financial_phrasebank", "data/FinancialPhraseBank-v1.0.zip", repo_type="dataset")
    with zipfile.ZipFile(path) as z:
        name = [n for n in z.namelist() if n.endswith(SUBSETS[subset])][0]
        raw = z.read(name).decode("latin-1")
    rows = []
    for line in raw.splitlines():
        if "@" in line:
            text, lab = line.rsplit("@", 1)
            rows.append((text.strip(), LABELS[lab.strip()]))
    return pd.DataFrame({"id": range(len(rows)), "text": [r[0] for r in rows], "label": [r[1] for r in rows]})


def load_split():
    """The fixed split of "sentences_allagree": stratified by label, seed SEED. Returns (train, val, test) DataFrames
    with columns id, text, label. `id` is the row number in the original file and identifies a test example."""
    df = load_phrasebank("allagree")
    rng = np.random.default_rng(SEED)
    parts = {0: [], 1: [], 2: []}
    for lab in (0, 1, 2):
        ids = df.index[df.label == lab].to_numpy().copy()
        rng.shuffle(ids)
        n = len(ids); a = int(round(FRACTIONS[0] * n)); b = a + int(round(FRACTIONS[1] * n))
        parts[lab] = (ids[:a], ids[a:b], ids[b:])
    out = []
    for k in range(3):
        ids = np.sort(np.concatenate([parts[lab][k] for lab in (0, 1, 2)]))
        out.append(df.loc[ids].reset_index(drop=True))
    return tuple(out)


def split_fingerprint(test):
    return hashlib.sha1(("|".join(f"{i}:{t}:{l}" for i, t, l in zip(test.id, test.text, test.label))).encode()).hexdigest()[:12]


def write_submission(outdir, predictions, trainable_params, toolkit, expected_trainable_lora, adapters_identity_at_init, seconds=None):
    """predictions: dict model_1..model_6 -> sequence of predicted labels (0/1/2), one per TEST example, in the order of load_split()'s test.
    trainable_params: dict model name -> int, counted from your model (parameters with requires_grad). seconds: optional dict model -> training seconds.
    Writes results.csv, predictions.csv, environment.txt."""
    _, _, test = load_split()
    missing = [m for m in MODELS if predictions.get(m) is None]
    if missing: raise ValueError(f"No predictions for {missing}: fill in the `predictions` dictionary for every model (one label per test example).")
    bad = [k for k in MODELS if trainable_params.get(k) is None]
    if bad: raise ValueError(f"No trainable-parameter count for {bad}: count them from your models (0 for model_1).")
    if expected_trainable_lora is None or adapters_identity_at_init is None: raise ValueError("Fill in expected_trainable_lora (your hand calculation) and adapters_identity_at_init (True or False).")
    os.makedirs(outdir, exist_ok=True)
    pred = pd.DataFrame({"id": test.id, "label": test.label})
    rows = []
    for m in MODELS:
        if m not in predictions or predictions[m] is None:
            continue
        p = np.asarray(predictions[m]); assert len(p) == len(test), f"{m}: expected {len(test)} predictions, got {len(p)}"
        pred[m] = p.astype(int)
        rows.append({"model": m, "test_accuracy": float((p == test.label.to_numpy()).mean()),
                     "trainable_params": int(trainable_params.get(m, -1)),
                     "seconds": (float(seconds[m]) if seconds and seconds.get(m) is not None else float("nan"))})
    res = pd.DataFrame(rows)
    res["toolkit"] = toolkit; res["expected_trainable_lora"] = expected_trainable_lora
    res["adapters_identity_at_init"] = bool(adapters_identity_at_init); res["split_fingerprint"] = split_fingerprint(test)
    res.to_csv(os.path.join(outdir, "results.csv"), index=False); pred.to_csv(os.path.join(outdir, "predictions.csv"), index=False)
    try: freeze = subprocess.run([sys.executable, "-m", "pip", "freeze"], capture_output=True, text=True, timeout=60).stdout
    except Exception: freeze = "(pip freeze unavailable)\n"
    env = f"python {platform.python_version()}\n" + freeze
    open(os.path.join(outdir, "environment.txt"), "w").write(env)
    return res


def check_submission(outdir):
    """Re-read the files, recompute the accuracies from predictions.csv, and print the summary the grader reads first."""
    _, _, test = load_split()
    res = pd.read_csv(os.path.join(outdir, "results.csv")); pred = pd.read_csv(os.path.join(outdir, "predictions.csv"))
    ok = True
    def line(name, value, good=None):
        nonlocal ok
        ok = ok and (good is not False)
        print(f"{name:34s} {value}" + ("" if good is None else ("   OK" if good else "   <-- PROBLEM")))
    line("split fingerprint (expect %s)" % split_fingerprint(test), res.split_fingerprint.iloc[0], res.split_fingerprint.iloc[0] == split_fingerprint(test))
    line("test examples", len(pred), len(pred) == len(test) and (pred.id.to_numpy() == test.id.to_numpy()).all())
    line("toolkit", res.toolkit.iloc[0])
    for _, r in res.iterrows():
        again = float((pred[r.model].to_numpy() == pred.label.to_numpy()).mean())
        line(f"{r.model} accuracy", f"accuracy {r.test_accuracy:.3f}  trainable {int(r.trainable_params):,}  time {r.seconds:.0f}s", abs(again - r.test_accuracy) < 1e-9)
    have = set(res.model); line("models reported", ", ".join(sorted(have)), set(MODELS) <= have)
    if "model_6" in have:
        t6 = int(res.set_index("model").loc["model_6", "trainable_params"]); e6 = int(res.expected_trainable_lora.iloc[0])
        line("model_6 trainable = hand calculation", f"{t6:,} vs {e6:,}", t6 == e6)
    line("adapters identity at init", res.adapters_identity_at_init.iloc[0], bool(res.adapters_identity_at_init.iloc[0]))
    print("ALL CHECKS PASS" if ok else "SOME CHECKS FAILED: fix them before you submit")
    return ok
